#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int u, v, sum;
} Edge;

int cmp(const void *a, const void *b) {
    Edge *ea = (Edge*)a;
    Edge *eb = (Edge*)b;
    return eb->sum - ea->sum;
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);
    Edge *edges = (Edge*)malloc(2 * M * sizeof(Edge));
    int *degree = (int*)calloc(N + 1, sizeof(int));
    int idx = 0;
    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        degree[a]++;
        degree[b]++;
        edges[idx].u = a; edges[idx].v = b; edges[idx].sum = a + b; idx++;
        edges[idx].u = b; edges[idx].v = a; edges[idx].sum = a + b; idx++;
    }
    qsort(edges, 2 * M, sizeof(Edge), cmp);

    int *best_odd_for_v = (int*)malloc((N + 1) * sizeof(int));
    int *best_even_for_u = (int*)malloc((N + 1) * sizeof(int));
    int *start_best = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) {
        best_odd_for_v[i] = -1;
        best_even_for_u[i] = -1;
        start_best[i] = -1;
    }

    for (int i = 0; i < 2 * M; i++) {
        int u = edges[i].u;
        int v = edges[i].v;
        int max_odd = best_odd_for_v[v];
        int F_even = (max_odd >= 0) ? max_odd + 1 : 0;
        int max_even = best_even_for_u[u];
        int F_odd = (max_even >= 0) ? max_even + 1 : 0;
        if (F_odd > best_odd_for_v[v]) best_odd_for_v[v] = F_odd;
        if (F_even > best_even_for_u[u]) best_even_for_u[u] = F_even;
        if (F_even > start_best[u]) start_best[u] = F_even;
    }

    for (int i = 1; i <= N; i++) {
        int ans;
        if (degree[i] == 0) ans = 1;
        else ans = 2 + start_best[i];
        printf("%d", ans);
        if (i < N) printf(" ");
    }
    printf("\n");

    free(edges);
    free(degree);
    free(best_odd_for_v);
    free(best_even_for_u);
    free(start_best);
    return 0;
}
