typedef struct {
    int u, v;
} Edge;

int cmp(const void *a, const void *b) {
    Edge *ea = (Edge*)a;
    Edge *eb = (Edge*)b;
    if (ea->u != eb->u) return ea->u - eb->u;
    return ea->v - eb->v;
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);
    int E = 2 * M;
    Edge *edges = (Edge*)malloc(E * sizeof(Edge));
    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        int u1 = N + 1 - a;
        int v1 = N + 1 - b;
        int u2 = N + 1 - b;
        int v2 = N + 1 - a;
        edges[2*i].u = u1;
        edges[2*i].v = v1;
        edges[2*i+1].u = u2;
        edges[2*i+1].v = v2;
    }
    qsort(edges, E, sizeof(Edge), cmp);

    int *bestE = (int*)calloc(N + 1, sizeof(int));
    int *bestO = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) bestO[i] = 1;
    int *O = (int*)malloc((N + 1) * sizeof(int));
    int *Earr = (int*)malloc((N + 1) * sizeof(int));
    int *temp = (int*)malloc((N + 1) * sizeof(int));

    int idx = 0;
    for (int x = 1; x <= N; x++) {
        int start = idx;
        while (idx < E && edges[idx].u == x) {
            idx++;
        }
        int deg = idx - start;

        // Compute O[x]
        int maxE = 0;
        for (int i = start; i < idx; i++) {
            int v = edges[i].v;
            if (bestE[v] > maxE) maxE = bestE[v];
        }
        O[x] = (1 > 1 + maxE) ? 1 : 1 + maxE;

        // Compute E[x]
        int maxO = 0;
        for (int i = start; i < idx; i++) {
            int v = edges[i].v;
            if (bestO[v] > maxO) maxO = bestO[v];
        }
        if (maxO > 0) Earr[x] = maxO + 1;
        else Earr[x] = 0;

        // Update bestE
        int pref = 0;
        for (int i = start; i < idx; i++) {
            int v = edges[i].v;
            temp[i - start] = pref + 2;
            if (bestE[v] > pref) pref = bestE[v];
        }
        for (int i = start; i < idx; i++) {
            int v = edges[i].v;
            if (temp[i - start] > bestE[v]) bestE[v] = temp[i - start];
        }

        // Update bestO
        pref = 0;
        for (int i = start; i < idx; i++) {
            int v = edges[i].v;
            if (pref > 0) temp[i - start] = pref + 2;
            else temp[i - start] = 0;
            if (bestO[v] > pref) pref = bestO[v];
        }
        for (int i = start; i < idx; i++) {
            int v = edges[i].v;
            if (temp[i - start] > bestO[v]) bestO[v] = temp[i - start];
        }
    }

    int *ans = (int*)malloc((N + 1) * sizeof(int));
    for (int v = 1; v <= N; v++) {
        int maxEnd = (O[v] > Earr[v]) ? O[v] : Earr[v];
        ans[N + 1 - v] = maxEnd;
